insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('483e33c0-71ee-5500-a281-b2a4a61e3cba', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'c9d3f8d8-91a5-567d-acd8-76be1b1d5eba', null, 'Describe the structure of a data packet.', '["A header, a footer and a checksum","A payload, an address and a key","A header, a payload and a trailer","A header, a body and a password"]'::jsonb, 'Every packet has a header (addresses, packet number), the payload (data) and a trailer (error check, end marker).', false, 'paper', '2.1 Data transmission', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('483e33c0-71ee-5500-a281-b2a4a61e3cba', 2, 'For 3 marks name all three parts AND say what each holds: header (source and destination IP addresses, packet number), payload (the actual data), trailer (end-of-packet marker and an error check such as a checksum).') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('8d670c8e-d654-5d97-ae0f-80e83a9cbc35', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'c9d3f8d8-91a5-567d-acd8-76be1b1d5eba', null, 'Explain how packet switching sends a file across a network.', '["Packets are sent one at a time only after the last one arrives","Every packet must follow the same fixed route to the receiver","Packets may take different routes and are reordered on arrival","The whole file is sent in one piece along the fastest route"]'::jsonb, 'Each packet travels independently; the packet number in the header lets the receiver put them back in order.', false, 'paper', '2.1 Data transmission', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('8d670c8e-d654-5d97-ae0f-80e83a9cbc35', 2, 'Score marks in sequence: data split into packets → each packet given a header → packets sent independently, possibly by different routes (routers choose) → may arrive out of order → reassembled using the packet numbers.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('bece30f3-8006-57b4-ab19-543a1974531e', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'c9d3f8d8-91a5-567d-acd8-76be1b1d5eba', null, 'Give a reason why parallel transmission is not suitable over long distances.', '["The bits can arrive out of step (skew)","It only works in one direction at once","It can only send one bit at a time","It cannot be used with USB devices"]'::jsonb, 'Over long wires the bits sent together arrive at different times (skew), so the data can be corrupted.', false, 'paper', '2.1 Data transmission', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('bece30f3-8006-57b4-ab19-543a1974531e', 0, 'Name the problem precisely: data skew, where bits sent at the same time arrive at slightly different times, and crosstalk between the wires. ''It''s slow'' is wrong: parallel is faster over short distances.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('787fabb3-ec12-5029-abb4-046d451c6054', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'c9d3f8d8-91a5-567d-acd8-76be1b1d5eba', null, 'A walkie-talkie lets users talk both ways, but not at the same time. Identify the type of transmission.', '["Half-duplex","Full-duplex","Simplex","Parallel"]'::jsonb, 'Both directions are possible, but only one at a time, so it is half-duplex.', false, 'paper', '2.1 Data transmission', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('787fabb3-ec12-5029-abb4-046d451c6054', 0, 'Learn the three directions with an example each: simplex (one way only, e.g. computer → printer), half-duplex (both ways, not at once, e.g. walkie-talkie), full-duplex (both ways at once, e.g. phone call).') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('dbc32398-c9a8-5bc0-a41a-4d604ddca8b7', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'c9d3f8d8-91a5-567d-acd8-76be1b1d5eba', null, 'Give a benefit of using a USB connection.', '["Devices are recognised automatically when plugged in","Data can be sent over any distance without loss","It sends many bits at once down parallel wires","It never needs a driver for any type of device"]'::jsonb, 'USB is plug-and-play: the computer detects the device and loads the driver automatically.', false, 'paper', '2.1 Data transmission', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('dbc32398-c9a8-5bc0-a41a-4d604ddca8b7', 0, 'USB benefits that score: automatic detection, only fits one way, standard connector (works with many devices), supplies power, backward compatible. A drawback to know: limited cable length.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('beb40d95-01f8-58c3-a157-a3c8005c2ef4', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'c9d3f8d8-91a5-567d-acd8-76be1b1d5eba', null, 'Data is sent using even parity. The byte 1011 0110 arrives. What should the receiver decide?', '["The byte is correct, because there are five 1s","An error has occurred, because there are five 1s","An error has occurred, because there are four 1s","The byte is correct, because there are four 1s"]'::jsonb, '1+0+1+1+0+1+1+0 = 5, an odd number, but even parity needs an even count, so there is an error.', false, 'paper', '2.2 Error detection', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('beb40d95-01f8-58c3-a157-a3c8005c2ef4', 1, 'Count every 1, including the parity bit, and say the count in your answer: ''there are five 1s, which is odd, so with even parity an error is detected''. Also know the limits: parity can''t find WHICH bit flipped, and misses two flipped bits.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('ec02b019-6fc8-52cf-abe6-0e54e6dfa4a2', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'c9d3f8d8-91a5-567d-acd8-76be1b1d5eba', null, 'Describe how an echo check works.', '["An extra bit makes the total number of 1s even or odd","The receiver sends the data back and the sender compares it","The sender adds a calculated value that the receiver checks","The receiver sends an acknowledgement before a timeout ends"]'::jsonb, 'The data is echoed back to the sender and compared with the original.', false, 'paper', '2.2 Error detection', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('ec02b019-6fc8-52cf-abe6-0e54e6dfa4a2', 1, 'Two steps for 2 marks: the data is sent back from the receiver to the sender, then the sender compares it with the original; if they differ, an error occurred. Know the drawback: the error might have happened on the way back.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('0d79bb47-ec06-5ea1-a114-b22370991b9e', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'c9d3f8d8-91a5-567d-acd8-76be1b1d5eba', null, 'Explain how an automatic repeat request (ARQ) detects and corrects errors.', '["A value calculated from the data is compared by the receiver and sender","The last digit is worked out from the others and checked on entry","The receiver counts the 1s and rejects any byte with the wrong parity","A missing acknowledgement before the timeout makes the sender resend"]'::jsonb, 'ARQ relies on acknowledgements and a timeout; anything not acknowledged in time is sent again.', false, 'paper', '2.2 Error detection', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('0d79bb47-ec06-5ea1-a114-b22370991b9e', 3, 'Use the key words: acknowledgement (positive/negative), timeout, resend. Receiver checks the data → sends a positive acknowledgement if correct or a negative one if not → no acknowledgement before the timeout → the data is resent.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('a1ac54a3-72bc-5b66-a08a-6a378a84a587', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'c9d3f8d8-91a5-567d-acd8-76be1b1d5eba', null, 'Where is a check digit typically used?', '["To encrypt data before it is transmitted","Inside every packet header sent on a network","On barcodes and ISBNs to catch input errors","To make the number of 1s in a byte even"]'::jsonb, 'The final digit is calculated from the others, so a mistyped or misread code can be detected.', false, 'paper', '2.2 Error detection', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('a1ac54a3-72bc-5b66-a08a-6a378a84a587', 2, 'A check digit catches errors when data is ENTERED (typed or scanned), not during transmission. Examples: ISBN, barcodes. Errors it catches: an incorrect digit, transposed digits, an omitted or extra digit.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('662eae73-7306-5d3d-a6c1-969889f2fbb2', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'c9d3f8d8-91a5-567d-acd8-76be1b1d5eba', null, 'Explain the difference between symmetric and asymmetric encryption.', '["Symmetric needs no key at all; asymmetric uses one secret shared key","Symmetric uses one shared key; asymmetric uses a public and a private key","Symmetric uses a public and a private key; asymmetric uses one shared key","Symmetric encrypts text only; asymmetric encrypts images and sound only"]'::jsonb, 'Symmetric: one key for both. Asymmetric: public key to encrypt, private key to decrypt.', false, 'paper', '2.3 Encryption', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('662eae73-7306-5d3d-a6c1-969889f2fbb2', 1, 'Name both sides: symmetric = the same key encrypts and decrypts (the key must be shared securely). Asymmetric = a public key encrypts and only the matching private key decrypts. Mention plaintext → ciphertext.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('fb13cdfc-a8e3-5414-abdc-15342952201b', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', '370a13a2-14d8-5bde-a83e-93460980a1aa', null, 'State the name of the register that holds the address of the next instruction to be fetched.', '["Memory Address Register (MAR)","Program Counter (PC)","Current Instruction Register (CIR)","Memory Data Register (MDR)"]'::jsonb, 'The PC always points to the next instruction. The MAR holds the address being accessed right now.', false, 'paper', '3.1 Computer architecture', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('fb13cdfc-a8e3-5414-abdc-15342952201b', 1, '''State'' = a short answer, no explanation needed. Write the full name and the abbreviation: ''Program Counter (PC)''. Just ''counter'' gets no mark.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('27b6948e-f478-5eb9-a574-b7d8ee832c8c', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', '370a13a2-14d8-5bde-a83e-93460980a1aa', null, 'In the fetch stage of the fetch–decode–execute cycle, what happens first?', '["The control unit decodes the instruction","The instruction in the MDR is copied to the CIR","The address in the PC is copied to the MAR","The value in the PC is incremented by 1"]'::jsonb, 'Fetch starts by copying the PC into the MAR so the CPU knows which memory location to read.', false, 'paper', '3.1 Computer architecture', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('27b6948e-f478-5eb9-a574-b7d8ee832c8c', 2, 'For a ''Describe the fetch stage'' question, give the steps in order, one mark each: PC → MAR, address sent on the address bus, instruction comes back on the data bus into the MDR, MDR → CIR, PC incremented. Name the buses for full marks.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('b110aea3-0f32-56a4-a2d7-c8f2fa265442', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', '370a13a2-14d8-5bde-a83e-93460980a1aa', null, 'Identify the bus that carries data in one direction only, from the CPU to memory.', '["Data bus","Address bus","Serial bus","Control bus"]'::jsonb, 'Addresses only go from the CPU (MAR) to memory, so the address bus is one-way.', false, 'paper', '3.1 Computer architecture', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('b110aea3-0f32-56a4-a2d7-c8f2fa265442', 1, '''Identify'' = name it. If asked to explain, add the reason: the CPU only ever sends addresses to memory, so the address bus is unidirectional. The data and control buses are bidirectional.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('bca75f3b-6e4d-5884-a711-da4e22c621e2', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', '370a13a2-14d8-5bde-a83e-93460980a1aa', null, 'Which register stores the data or instruction that has just been fetched from memory?', '["Memory Address Register (MAR)","Accumulator (ACC)","Memory Data Register (MDR)","Program Counter (PC)"]'::jsonb, 'The MDR holds whatever has just been read from, or is about to be written to, memory.', false, 'paper', '3.1 Computer architecture', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('bca75f3b-6e4d-5884-a711-da4e22c621e2', 2, 'Mark schemes accept ''MDR'' or ''memory data register''. A common lost mark: mixing up MAR (an address) with MDR (the data at that address). Address = A, Data = D.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('0b0cd6ca-9530-5936-a148-30fc40d948df', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', '370a13a2-14d8-5bde-a83e-93460980a1aa', null, 'Describe the role of the Arithmetic Logic Unit (ALU).', '["It holds frequently used data close to the CPU","It sends control signals to all of the other components","It stores the address of the next instruction","It carries out calculations and logical comparisons"]'::jsonb, 'The ALU does the maths and the logic. The control unit is the one that sends control signals.', false, 'paper', '3.1 Computer architecture', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('0b0cd6ca-9530-5936-a148-30fc40d948df', 3, 'For 2 marks give two separate points: performs arithmetic (add, subtract) AND performs logic operations (comparisons such as AND, OR, greater than). It can also be credited for using the accumulator to hold results.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('9d840483-0d07-5048-ae82-e5cdd8219418', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', '370a13a2-14d8-5bde-a83e-93460980a1aa', null, 'Explain why increasing the size of the cache can improve the performance of a CPU.', '["The CPU can carry out many more cycles every second","More data can be read without having to fetch it from RAM","Secondary storage can be accessed much more quickly too","Each core is then able to process two instructions at once"]'::jsonb, 'Cache is much faster than RAM. A bigger cache means more of what the CPU needs is already there.', false, 'paper', '3.1 Computer architecture', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('9d840483-0d07-5048-ae82-e5cdd8219418', 1, '''Explain'' needs a point plus a reason. Point: more data/instructions can be stored in cache. Reason: cache is faster to access than RAM, so the CPU waits less. One-word answers like ''faster'' score nothing.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('38f73964-e177-5ed6-a244-4813ab250f8f', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', '370a13a2-14d8-5bde-a83e-93460980a1aa', null, 'A computer''s processor is upgraded from 2 cores to 4 cores. Explain why its performance may not double.', '["Cores share one register, so only one can run","Some programs cannot be split to run on several cores","Extra cores reduce the amount of cache available","Each extra core added makes the clock speed much slower"]'::jsonb, 'If a task can''t be split into parallel parts, extra cores sit idle.', false, 'paper', '3.1 Computer architecture', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('38f73964-e177-5ed6-a244-4813ab250f8f', 1, 'Examiners want the limitation, not just ''more cores = faster''. Good points: software must be written to use multiple cores, and cores must communicate, which takes time.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('255fa4d5-75fc-5388-aa5f-a7bc436b8471', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', '370a13a2-14d8-5bde-a83e-93460980a1aa', null, 'Which device is most likely to contain an embedded system?', '["A school file server","A laptop computer","A washing machine","A desktop gaming PC"]'::jsonb, 'An embedded system does one dedicated job inside a bigger device, like controlling a wash cycle.', false, 'paper', '3.1 Computer architecture', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('255fa4d5-75fc-5388-aa5f-a7bc436b8471', 2, 'When asked to describe an embedded system, say it is a computer system built into a larger device, with a dedicated function. Then give a clear example such as a washing machine, microwave or car engine management system. General-purpose computers are not embedded.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('f4b9c463-efd8-5788-a385-35c34cbead90', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', '370a13a2-14d8-5bde-a83e-93460980a1aa', null, 'Describe how a capacitive touch screen detects where it has been touched.', '["The finger changes the electrostatic field at that point","A grid of infrared beams is broken by the finger","Pressure sensors measure how hard the screen is pressed","Two flexible layers are pressed together to complete a circuit"]'::jsonb, 'Your finger is conductive, so it disturbs the screen''s electrostatic field. The processor works out where.', false, 'paper', '3.2 Input and output devices', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('f4b9c463-efd8-5788-a385-35c34cbead90', 0, 'Typical 3-mark answer: the screen has a conductive layer and an electrostatic field; touching it changes the field/charge at that point; the change is measured to calculate the coordinates. Pressing layers together describes a resistive screen.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('eb90df7a-c982-5f6a-a179-cd77e5785fa5', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', '370a13a2-14d8-5bde-a83e-93460980a1aa', null, 'Identify the most suitable sensor to switch street lights on automatically when it gets dark.', '["Pressure sensor","Light sensor","Humidity sensor","Moisture sensor"]'::jsonb, 'The amount of light is what changes at dusk, so a light sensor is used.', false, 'paper', '3.2 Input and output devices', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('eb90df7a-c982-5f6a-a179-cd77e5785fa5', 1, 'For sensor questions, link the sensor to what it measures: light level. If asked how the system works, say the sensor sends data to a microprocessor, which compares it with a stored value and switches the light (actuator) on when it is below the value.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('1dc6576b-bb43-5772-aa06-f18c9eb02874', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', '370a13a2-14d8-5bde-a83e-93460980a1aa', null, 'Which statement describes ROM?', '["Non-volatile and stores the start-up (bootstrap) instructions","Volatile and holds the data and programs that are currently running","Volatile memory used as a cache inside the CPU","Secondary storage that holds the user''s saved files"]'::jsonb, 'ROM keeps its contents when power is off and holds the instructions used to start the computer.', false, 'paper', '3.3 Data storage', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('1dc6576b-bb43-5772-aa06-f18c9eb02874', 0, 'RAM vs ROM questions: one mark per difference. Use the key words volatile / non-volatile, read and write / read only, and what each stores (currently running data and programs / the bootstrap).') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('64142a54-7b0c-55af-a0bf-fba901326868', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', '370a13a2-14d8-5bde-a83e-93460980a1aa', null, 'Describe how data is stored on a magnetic hard disk drive.', '["Capacitors in memory chips are charged","Areas of a spinning platter are magnetised","Pits are burnt into a reflective layer","Electrons are trapped inside NAND flash memory cells"]'::jsonb, 'A read/write head magnetises tiny areas of the spinning platter; the direction represents 1 or 0.', false, 'paper', '3.3 Data storage', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('64142a54-7b0c-55af-a0bf-fba901326868', 1, 'Key words that score: platters, spin, read/write head moves across, tracks and sectors, magnetised to represent 1 or 0. Flash cells describe SSDs and pits describe optical discs, so don''t mix them up.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('243066b4-1789-5496-a1ae-2f3a4a716d1a', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', '370a13a2-14d8-5bde-a83e-93460980a1aa', null, 'A photographer uses a laptop outdoors. Explain why solid-state storage is suitable.', '["It has no moving parts, so it is less likely to be damaged","It is volatile, so data is wiped if the laptop is stolen","It has a much larger capacity than any hard disk drive","It is cheaper per gigabyte than a magnetic hard disk"]'::jsonb, 'With no moving parts, solid-state storage survives knocks much better than a spinning hard disk.', false, 'paper', '3.3 Data storage', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('243066b4-1789-5496-a1ae-2f3a4a716d1a', 0, 'Always tie the reason to the scenario: no moving parts, so it is not damaged if the laptop is knocked or dropped outdoors; it also uses less power, so the battery lasts longer. A generic ''it is faster'' without context scores less.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('d6d44298-12b8-55cd-a432-699502d5b114', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', '370a13a2-14d8-5bde-a83e-93460980a1aa', null, 'Explain what is meant by virtual memory.', '["Cache memory that is built into the processor itself","ROM that is used to store the computer''s start-up instructions","Part of secondary storage used as extra RAM when RAM is full","A copy of RAM saved in the cloud in case of power failure"]'::jsonb, 'When RAM runs out, the OS moves unused pages to the hard disk or SSD to free space.', false, 'paper', '3.3 Data storage', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('d6d44298-12b8-55cd-a432-699502d5b114', 2, 'For 3 marks: it is an area of secondary storage, used when RAM is full, and data not needed right now is moved there (paged out) and swapped back when needed. Mention that it is slower than RAM.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('fb013dd3-7724-5406-aa2f-adc2851ca250', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', '370a13a2-14d8-5bde-a83e-93460980a1aa', null, 'Which statement describes a MAC address?', '["A unique address given to the NIC by the manufacturer","The address of a web page that is typed into a browser","An address given by the router that can change over time","An address that identifies a whole network on the internet"]'::jsonb, 'A MAC address is set on the network interface card when it is made.', false, 'paper', '3.4 Network hardware', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('fb013dd3-7724-5406-aa2f-adc2851ca250', 0, 'MAC vs IP is a favourite. MAC: assigned by the manufacturer, unique, identifies the device''s NIC, usually does not change, written in hexadecimal. IP: assigned by the network, can change, identifies the device on a network or the internet.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('7c4197c2-0d62-5c7f-a196-e29f8392fa41', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', '370a13a2-14d8-5bde-a83e-93460980a1aa', null, 'Describe the role of a router in a network.', '["It stores web pages so that they load faster for users","It connects devices in one network using MAC addresses only","It converts digital signals to analogue for a telephone line","It forwards data packets between networks using IP addresses"]'::jsonb, 'Routers look at the destination IP address and send each packet on towards the right network.', false, 'paper', '3.4 Network hardware', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('7c4197c2-0d62-5c7f-a196-e29f8392fa41', 3, 'Router answers that score: receives data packets, reads the destination IP address, forwards packets to the next network/router, and can assign IP addresses to devices. ''Connects to the internet'' alone is too vague.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('c24f345a-d0af-5944-accc-c3d5f051a26a', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', '370a13a2-14d8-5bde-a83e-93460980a1aa', null, 'Explain the difference between a static IP address and a dynamic IP address.', '["Static is assigned each time a device connects; dynamic does not change","Static is used for home devices; dynamic is only used by web servers","Dynamic is set by the manufacturer; static is chosen by the user","Dynamic is assigned each time a device connects; static does not change"]'::jsonb, 'A dynamic address can change each time you connect. A static one stays fixed.', false, 'paper', '3.4 Network hardware', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('c24f345a-d0af-5944-accc-c3d5f051a26a', 3, 'Describe both sides of the difference: static stays the same / is permanently assigned; dynamic is assigned by the network each time the device connects and can change. A use case helps: web servers often use static addresses.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('b7b70310-b28c-5171-ac78-3310b58c58b4', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'b4554ed1-9472-5f54-af1e-bd8fb51a7b78', null, 'Identify which of these is system software.', '["Operating system","Photo editor","Web browser","Spreadsheet program"]'::jsonb, 'The operating system manages the hardware and runs other software, so it is system software.', false, 'paper', '4.1 Types of software', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('b7b70310-b28c-5171-ac78-3310b58c58b4', 0, 'System software runs and manages the computer (operating system, utility software). Application software lets the user do a task (spreadsheet, browser). In a tick-table question, read every row before ticking.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('bb069a84-a5bc-5a37-a789-817b88f9f195', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'b4554ed1-9472-5f54-af1e-bd8fb51a7b78', null, 'Which of these is a function of an operating system?', '["Translating source code into machine code","Checking documents for spelling mistakes","Managing the memory used by programs","Compressing photos before they are emailed"]'::jsonb, 'Allocating and managing memory is one of the OS''s core jobs. Translation is done by a translator.', false, 'paper', '4.1 Types of software', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('bb069a84-a5bc-5a37-a789-817b88f9f195', 2, 'For ''Describe three functions'', name each function AND say what it does: memory management (allocates RAM to programs), file management (creates, saves, deletes files), security (user accounts), peripheral management (drivers), multitasking, providing an interface, interrupt handling.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('dd227ecd-1a58-517a-aec9-9d128a27138d', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'b4554ed1-9472-5f54-af1e-bd8fb51a7b78', null, 'Explain what is meant by an interrupt.', '["A program that removes viruses from the hard disk","An instruction that is written in assembly language","An error that stops the computer from ever working again","A signal sent to the processor to ask for its attention"]'::jsonb, 'An interrupt is a signal asking the CPU to stop and deal with something.', false, 'paper', '4.1 Interrupts', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('dd227ecd-1a58-517a-aec9-9d128a27138d', 3, 'Two marks: it is a signal (from hardware or software) and it tells the processor that something needs attention. Adding an example such as ''a key is pressed'' can earn a further mark.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('f2015190-bfcc-5d3d-af74-1d2b502d65b8', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'b4554ed1-9472-5f54-af1e-bd8fb51a7b78', null, 'Which event would cause a software interrupt?', '["A program tries to divide a number by zero","A key is pressed on the keyboard by a user","The printer runs out of paper while printing","The mouse is moved across the desk by the user"]'::jsonb, 'Division by zero comes from a running program, so it is a software interrupt. The others come from hardware.', false, 'paper', '4.1 Interrupts', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('f2015190-bfcc-5d3d-af74-1d2b502d65b8', 0, 'Know examples of both types. Hardware: a key press, a mouse move, the printer is out of paper. Software: division by zero, two programs trying to use the same memory. The examiner will not accept the same example twice.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('e2212e9a-9ac9-5ba5-adab-4144da122156', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'b4554ed1-9472-5f54-af1e-bd8fb51a7b78', null, 'An interrupt is received. What does the processor do at the end of the current fetch–decode–execute cycle?', '["It ignores the signal until the program has ended","It restarts the whole computer straight away","It saves the current state of the running task","It deletes the program that was running"]'::jsonb, 'The CPU saves where it was, runs the interrupt service routine, then restores the state and continues.', false, 'paper', '4.1 Interrupts', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('e2212e9a-9ac9-5ba5-adab-4144da122156', 2, 'Describe the full sequence for 3–4 marks: checks for interrupts at the end of each FDE cycle, checks the priority, saves the current task''s state (registers), runs the interrupt service routine (ISR), then restores the state and carries on.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('d23de070-a63a-544a-a094-1892b6216d37', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'b4554ed1-9472-5f54-af1e-bd8fb51a7b78', null, 'Explain how firmware is used when a computer is switched on.', '["It translates assembly code into binary machine code","It is installed by the user to edit their documents","It is hardware that holds the operating system","It is stored in ROM and loads the operating system"]'::jsonb, 'The firmware, or bootloader, in ROM starts the hardware and loads the OS into RAM.', false, 'paper', '4.1 Types of software', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('d23de070-a63a-544a-a094-1892b6216d37', 3, 'Hardware, firmware, OS and applications questions want the chain: firmware (the bootloader, held in ROM) loads the operating system; the OS provides the environment that applications run in; applications run on top of the OS.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('a1a558b9-8443-57b5-a841-be5337c3eef9', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'b4554ed1-9472-5f54-af1e-bd8fb51a7b78', null, 'Give an advantage of writing a program in a high-level language.', '["It gives direct control of the hardware","It is easier to read, write and debug","It always runs faster than machine code","It does not need a translator to run"]'::jsonb, 'English-like keywords make high-level code easier for people to read and fix.', false, 'paper', '4.2 Programming languages', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('a1a558b9-8443-57b5-a841-be5337c3eef9', 1, 'Good high-level points: easier to understand, debug and maintain, uses English-like statements, and is portable to different types of machine. ''Easier'' alone is too vague; say what is easier.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('6cec1f86-835e-5447-ad5d-af59f527f4e7', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'b4554ed1-9472-5f54-af1e-bd8fb51a7b78', null, 'Give a reason why a programmer might choose to write in assembly language.', '["To have direct control of specific hardware","So that beginners find the code easier to read","To make the code portable to any type of CPU","So that the code needs no translation at all"]'::jsonb, 'Assembly maps closely to machine code, so it gives precise control over the hardware.', false, 'paper', '4.2 Programming languages', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('6cec1f86-835e-5447-ad5d-af59f527f4e7', 0, 'Assembly language reasons that score: direct manipulation of hardware or registers, code can be made more efficient (faster, uses less memory), and it is useful for embedded systems. Remember: assembly still needs an assembler.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('7bdf6e86-2572-5894-a236-b0d5eea758a9', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'b4554ed1-9472-5f54-af1e-bd8fb51a7b78', null, 'Which statement describes a compiler?', '["It translates and then runs the program one line at a time","It translates assembly language into machine code","It translates the whole program into an executable file","It checks the program for logic errors only"]'::jsonb, 'A compiler translates the whole program once and creates an executable that runs without the compiler.', false, 'paper', '4.2 Translators', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('7bdf6e86-2572-5894-a236-b0d5eea758a9', 2, 'Compiler: translates all the code in one go, produces an executable file, and reports all errors at the end. Interpreter: translates and runs line by line, and stops at the first error. Assembler: assembly to machine code.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('3897c252-0696-5950-a226-b31d7f75438d', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'b4554ed1-9472-5f54-af1e-bd8fb51a7b78', null, 'A programmer is writing a game. Explain why she uses an interpreter while writing it.', '["It produces an executable file that she can share with all users","The final game will run faster than compiled code","It hides the source code so nobody can copy the game","It stops at the first error, so she can fix it straight away"]'::jsonb, 'An interpreter stops where the error is, which makes debugging during development quick.', false, 'paper', '4.2 Translators', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('3897c252-0696-5950-a226-b31d7f75438d', 3, 'Scenario questions need the reason linked to development: errors are reported line by line or one at a time, she can test and debug part of the program, and there''s no need to recompile after every change.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('691e31d1-4280-5d6c-aabd-6ddfdf161b4f', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'b4554ed1-9472-5f54-af1e-bd8fb51a7b78', null, 'Explain why the programmer uses a compiler when the game is released to customers.', '["Errors are shown to the customers one line at a time as it runs","Customers can easily edit the code to change the game","The game will only work on the programmer''s own computer","Customers can run it without the source code or a translator"]'::jsonb, 'The executable runs on its own and keeps the source code private.', false, 'paper', '4.2 Translators', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('691e31d1-4280-5d6c-aabd-6ddfdf161b4f', 3, 'Release reasons that score: it produces an executable, so users don''t need a translator; the source code is not shared, so it can''t be copied or edited; the compiled program runs faster.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('15824ae0-ab19-5788-a14b-e2be9a9d3b70', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'b4554ed1-9472-5f54-af1e-bd8fb51a7b78', null, 'Which translator converts assembly language into machine code?', '["Debugger","Interpreter","Compiler","Assembler"]'::jsonb, 'An assembler translates each assembly mnemonic into its machine code instruction.', false, 'paper', '4.2 Translators', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('15824ae0-ab19-5788-a14b-e2be9a9d3b70', 3, 'This is a one-mark ''State'' question. For translator tables, assembler = assembly → machine code; compilers and interpreters translate high-level languages. A debugger is a tool, not a translator.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('76d3edf1-452d-5d01-a03d-6b4157b1d26a', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'b4554ed1-9472-5f54-af1e-bd8fb51a7b78', null, 'Which IDE feature lets a programmer run a program one line at a time to find an error?', '["A built-in code editor","Stepping through with breakpoints","Prettyprinting the code to find bugs","Auto-completion of all keywords"]'::jsonb, 'Breakpoints pause the program and stepping runs it line by line, so you can watch variables change.', false, 'paper', '4.2 IDEs', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('76d3edf1-452d-5d01-a03d-6b4157b1d26a', 1, 'For ''Describe four features of an IDE'', name the feature and say how it helps: code editor (write code), run-time environment (run it), translator (compile or interpret), error diagnostics (highlight errors), auto-completion, auto-correction, prettyprint (colours and indents code).') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('4855f731-1757-5250-a27c-b55c094b11e7', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'b4554ed1-9472-5f54-af1e-bd8fb51a7b78', null, 'Describe what error diagnostics in an IDE do.', '["They complete the keywords as the programmer types them","They highlight errors and suggest where the problem is","They translate the program into an executable file","They colour-code keywords and indent the code neatly"]'::jsonb, 'Error diagnostics point out mistakes and where they are.', false, 'paper', '4.2 IDEs', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('4855f731-1757-5250-a27c-b55c094b11e7', 1, 'Don''t just repeat the name of the feature. Describe it: it highlights or underlines errors, shows the line number, and gives a message explaining the error so it can be corrected.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('a845f48d-aafb-560e-a285-27510a5d206b', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'b4554ed1-9472-5f54-af1e-bd8fb51a7b78', null, 'Which is an example of utility software?', '["Word processing software","Presentation software","Anti-virus software","Web browsing software"]'::jsonb, 'Anti-virus protects the computer, so it is a utility. The others are application software.', false, 'paper', '4.1 Types of software', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('a845f48d-aafb-560e-a285-27510a5d206b', 2, 'Utility software maintains or protects the computer. Examples: anti-virus, defragmentation, backup, compression. If asked to describe one, say what it does, for example ''scans files and quarantines or deletes viruses''.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('fe485352-5ba5-571e-a049-c6a0539e7058', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'b4554ed1-9472-5f54-af1e-bd8fb51a7b78', null, 'Which order is correct when a computer starts up and a user opens an application?', '["The OS loads the firmware, then the firmware runs the application","The application runs directly without needing an OS","The application loads the OS, then the OS runs firmware","Firmware loads the OS, then the OS runs the application"]'::jsonb, 'Applications rely on the OS, and the OS is loaded by the firmware.', false, 'paper', '4.1 Types of software', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('fe485352-5ba5-571e-a049-c6a0539e7058', 3, 'This links all four layers. Write it as a chain in your answer: hardware → firmware (bootloader) → operating system → applications. Each layer depends on the one below it.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('09f5cf9d-e22c-52c4-a74d-3b077e6d366d', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'a2caa4b0-2816-5d4e-a1af-2e0a91a3745a', null, 'Explain the difference between the internet and the World Wide Web.', '["The internet is the network; the WWW is the web pages accessed over it","The WWW is the network; the internet is the web pages accessed over it","The internet is only used for email; the WWW is used for everything else","They are two names for exactly the same thing on any computer"]'::jsonb, 'The internet is the hardware network; the WWW is the content (web pages) that runs on it.', false, 'paper', '5.1 The internet and the WWW', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('09f5cf9d-e22c-52c4-a74d-3b077e6d366d', 0, 'Two marks, one per side: the internet is the infrastructure (a global network of connected computers/devices); the WWW is the collection of web pages and resources accessed using the internet (via HTTP and browsers).') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('5e2237b5-9389-58e8-af53-41aa0e42307b', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'a2caa4b0-2816-5d4e-a1af-2e0a91a3745a', null, 'State the role of the DNS when a user types a URL.', '["It finds the IP address that matches the domain name","It stores the web page so it loads faster next time","It encrypts the data sent between browser and server","It renders the HTML into a page the user can see"]'::jsonb, 'DNS translates a domain name into the web server''s IP address.', false, 'paper', '5.1 The internet and the WWW', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('5e2237b5-9389-58e8-af53-41aa0e42307b', 0, 'Give the sequence for full marks in a ''describe'' question: URL typed → browser sends the domain name to a DNS server → DNS returns the IP address (or asks another DNS server) → browser sends a request to that IP → web server returns the HTML → browser renders it.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('2e54a57c-1e41-5d8c-a866-3255206ee8aa', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'a2caa4b0-2816-5d4e-a1af-2e0a91a3745a', null, 'Give one function of a web browser.', '["It gives each device its MAC address","It renders HTML to display web pages","It splits files into data packets","It finds IP addresses for domains"]'::jsonb, 'A browser''s main job is to render (display) HTML from web servers.', false, 'paper', '5.1 The internet and the WWW', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('2e54a57c-1e41-5d8c-a866-3255206ee8aa', 1, 'Browser functions that score: renders HTML, stores bookmarks and history, manages cookies, provides navigation (back/forward), allows multiple tabs, checks for HTTPS/certificates. Give each as a separate point.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('2f4b428e-d630-5b3a-ad73-b19ec4ec1c43', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'a2caa4b0-2816-5d4e-a1af-2e0a91a3745a', null, 'Describe the difference between a session cookie and a persistent cookie.', '["A persistent cookie is deleted when the browser closes; a session one stays","A session cookie is stored on the server; a persistent one in the router","A session cookie stores passwords; a persistent one stores only adverts","A session cookie is deleted when the browser closes; a persistent one stays"]'::jsonb, 'Session cookies last one visit; persistent cookies stay on the device for future visits.', false, 'paper', '5.1 The internet and the WWW', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('2f4b428e-d630-5b3a-ad73-b19ec4ec1c43', 3, 'Two-part answer: session cookies are temporary (lost when the browser closes, e.g. a shopping basket). Persistent cookies are saved on the device until they expire or are deleted (e.g. remembering login details or preferences).') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('d06bf213-046f-5e34-a53a-84f3a3cca1b4', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'a2caa4b0-2816-5d4e-a1af-2e0a91a3745a', null, 'Explain how blockchain makes digital currency transactions secure.', '["Each transaction is checked by one bank that keeps the only copy","Every user''s password is stored inside each block of the chain","Each block links to the previous one, so past records can''t be changed","Transactions are encrypted with the same key that everyone shares"]'::jsonb, 'Blocks are linked by hashes, and many computers keep copies, so tampering is detected.', false, 'paper', '5.2 Digital currency', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('d06bf213-046f-5e34-a53a-84f3a3cca1b4', 2, 'Key words: decentralised (copies on many computers), each block holds a hash of the previous block, changing one block breaks the chain, new transactions verified by the network. It''s a time-stamped record.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('ae50fdd2-a4ce-5caa-a453-e613efd54443', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'a2caa4b0-2816-5d4e-a1af-2e0a91a3745a', null, 'Explain the difference between phishing and pharming.', '["Phishing infects files; pharming floods a web server with requests","Pharming uses fake emails; phishing redirects users to a fake website","Phishing uses fake emails; pharming redirects users to a fake website","Phishing guesses passwords; pharming records what the user types"]'::jsonb, 'Phishing needs you to click; pharming redirects you even if you type the correct address.', false, 'paper', '5.3 Cyber security', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('ae50fdd2-a4ce-5caa-a453-e613efd54443', 2, 'Name the mechanism of each: phishing = a legitimate-looking email that tricks the user into clicking a link and entering details. Pharming = malicious code (or a changed DNS entry) redirects the user to a fake site even when they type the correct URL.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('a88fe211-ce80-5fe8-a982-06ebb92e9bfe', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'a2caa4b0-2816-5d4e-a1af-2e0a91a3745a', null, 'Describe how a DDoS attack affects a web server.', '["It floods the server with requests so real users can''t access it","It records the keystrokes of everyone who logs in to the server","It encrypts the server''s files and demands a ransom to unlock them","It guesses every possible password until it finds the right one"]'::jsonb, 'Distributed denial of service: a flood of requests from many devices overwhelms the server.', false, 'paper', '5.3 Cyber security', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('a88fe211-ce80-5fe8-a982-06ebb92e9bfe', 0, 'Structure: many infected computers (a botnet) → send huge numbers of requests at once → the server is overwhelmed → it slows down or crashes → legitimate users are denied access. Protection: a firewall, a proxy server, anti-malware on devices.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('e013a8af-8093-58a8-a501-856f97daa21d', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'a2caa4b0-2816-5d4e-a1af-2e0a91a3745a', null, 'Which type of malware spreads across a network without any user action?', '["Trojan horse","Worm","Adware","Virus"]'::jsonb, 'A worm replicates by itself across a network; a virus needs the user to run an infected file.', false, 'paper', '5.3 Cyber security', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('e013a8af-8093-58a8-a501-856f97daa21d', 1, 'Contrast them in your answer: a worm replicates itself across networks on its own; a virus needs a host file and the user to run it; a Trojan is disguised as legitimate software the user installs.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('be0a71f0-83d3-53b4-a6a8-74005c71a807', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'a2caa4b0-2816-5d4e-a1af-2e0a91a3745a', null, 'Describe how a firewall protects a network.', '["It monitors traffic and blocks anything that breaks its set rules","It scans every file and deletes any viruses it finds inside them","It hides the user''s IP address by forwarding all of their requests","It encrypts all the data stored on the hard disk of the computer"]'::jsonb, 'A firewall filters traffic in and out against rules and blocks what isn''t allowed.', false, 'paper', '5.3 Cyber security', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('be0a71f0-83d3-53b4-a6a8-74005c71a807', 0, 'Points that score: sits between the network and the internet, monitors incoming and outgoing traffic, checks it against set rules/criteria, blocks unauthorised traffic, can block certain IP addresses or websites, keeps a log.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('3aad45b0-f134-5149-a253-5317b5ffccf1', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', 'a2caa4b0-2816-5d4e-a1af-2e0a91a3745a', null, 'Explain how two-step verification makes a login more secure.', '["Two different passwords are both stored on the same device","A code sent to a second device is needed as well as the password","The account is locked for good after two failed login attempts","The password is typed twice to make sure no mistake was made"]'::jsonb, 'A stolen password isn''t enough, because the attacker would also need the code sent to the user''s device.', false, 'paper', '5.3 Cyber security', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('3aad45b0-f134-5149-a253-5317b5ffccf1', 1, 'Explain the ''two factors'': something you know (password) + something you have (a phone receiving a one-time code). Even if the password is stolen, the attacker doesn''t have the code.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('2ff5ce94-0f73-594c-aa83-086578d0b9d9', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', '7f09772a-bb5c-5ea8-abf7-da1bb142f3d8', null, 'Identify the three main parts of an automated system.', '["Actuators, a router and a hard disk","A monitor, a mouse and a microprocessor","Sensors, a printer and a keyboard","Sensors, a microprocessor and actuators"]'::jsonb, 'Input (sensors) → process (microprocessor) → output (actuators), with no human involved.', false, 'paper', '6.1 Automated systems', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('2ff5ce94-0f73-594c-aa83-086578d0b9d9', 3, 'Always describe the flow: sensors collect data (input) → microprocessor processes it and compares with stored values → actuators carry out the action (output). Mention it repeats continuously.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('0ec86a73-11e2-510e-a51d-7e005aba60f5', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', '7f09772a-bb5c-5ea8-abf7-da1bb142f3d8', null, 'Describe how a microprocessor keeps a greenhouse at the right temperature.', '["It compares sensor readings with a stored value and switches the heater","It stores sensor readings and waits for a gardener to switch the heater","It sets the heater to full power all the time so it can never get cold","It sends readings to the internet so the heater can decide what to do"]'::jsonb, 'Read → compare with a stored value → signal to the actuator → repeat.', false, 'paper', '6.1 Automated systems', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('0ec86a73-11e2-510e-a51d-7e005aba60f5', 0, 'The classic 6-mark answer: temperature sensor takes readings → sent to the microprocessor (via an ADC) → compared with a stored/preset value → if lower, a signal is sent to switch the heater on (if higher, turn it off / open windows with a motor) → the process repeats continuously.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('4f2f51b6-4c65-52d7-ac37-ceb708d03ca4', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', '7f09772a-bb5c-5ea8-abf7-da1bb142f3d8', null, 'Give an advantage of using an automated system in a factory.', '["It is cheap to buy and install at first","It always creates more jobs for workers","It can work 24/7 with consistent quality","It needs no maintenance or set-up costs"]'::jsonb, 'Machines don''t tire, so they can run all day and night with the same quality.', false, 'paper', '6.1 Automated systems', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('4f2f51b6-4c65-52d7-ac37-ceb708d03ca4', 2, 'Advantages: faster, works 24/7, consistent quality, safer for workers in dangerous tasks, fewer errors. Disadvantages: expensive to set up, maintenance, job losses, can''t adapt to unexpected problems. Always link to the scenario given.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('17b21c88-53f6-5a83-a34f-9222789c43af', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', '7f09772a-bb5c-5ea8-abf7-da1bb142f3d8', null, 'Which sensor would be most suitable to detect an intruder moving in a room?', '["Humidity sensor","pH sensor","Moisture sensor","Infrared sensor"]'::jsonb, 'Infrared sensors detect the heat or movement of a person.', false, 'paper', '6.1 Automated systems', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('17b21c88-53f6-5a83-a34f-9222789c43af', 3, 'Name the sensor AND why it fits: an infrared (or motion/PIR) sensor detects body heat or movement. In ''choose a sensor'' questions, link the sensor to exactly what changes in the scenario.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('15ba939e-7421-5ab4-a0f8-e743c9ed4f24', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', '7f09772a-bb5c-5ea8-abf7-da1bb142f3d8', null, 'Identify a characteristic of a robot.', '["It has a mechanical structure and is programmable","It can only work while a person controls it directly","It is always shaped to look like a human being","It never uses sensors to detect its surroundings"]'::jsonb, 'Robots are programmable machines with a mechanical structure, sensors and actuators.', false, 'paper', '6.2 Robotics', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('15ba939e-7421-5ab4-a0f8-e743c9ed4f24', 0, 'Three characteristics to learn: a mechanical structure or framework, electrical components (sensors, microprocessors, actuators), and being programmable. Robots don''t need to look human.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('043226eb-32e6-5a38-aba2-5a37e7a8904d', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', '7f09772a-bb5c-5ea8-abf7-da1bb142f3d8', null, 'Give a disadvantage of using robots instead of workers.', '["They cannot work in dangerous places","They get tired and need regular breaks","They are less accurate than people at work","They are expensive to buy and maintain"]'::jsonb, 'Robots cost a lot to buy, install and maintain, even though they work tirelessly.', false, 'paper', '6.2 Robotics', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('043226eb-32e6-5a38-aba2-5a37e7a8904d', 3, 'Disadvantages: high set-up and maintenance cost, job losses, can''t think creatively or handle unexpected situations, need reprogramming for new tasks. Balance with the advantages if the question says ''discuss''.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('6085c4ec-a8f1-5ca1-aad9-f635e7eada96', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', '7f09772a-bb5c-5ea8-abf7-da1bb142f3d8', null, 'Identify a characteristic of artificial intelligence.', '["It cannot process any new data","It can only follow fixed instructions","It can learn and adapt from data","It never makes any decisions itself"]'::jsonb, 'AI systems can learn from data and adapt how they behave.', false, 'paper', '6.3 Artificial intelligence', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('6085c4ec-a8f1-5ca1-aad9-f635e7eada96', 2, 'The characteristics Cambridge wants: the collection of data and rules, the ability to reason, and the ability to learn and adapt. AI simulates intelligent human behaviour.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('334d210a-cb1b-59a6-a9a2-fd410d884ce0', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', '7f09772a-bb5c-5ea8-abf7-da1bb142f3d8', null, 'Identify the main components of an expert system.', '["A sensor, a microprocessor, an actuator and a feedback loop","A knowledge base, a rule base, an inference engine and an interface","A browser, a web server, a DNS server and a firewall to block attacks","A compiler, an interpreter, an assembler and an IDE"]'::jsonb, 'An expert system uses a knowledge base and rule base, an inference engine and an interface.', false, 'paper', '6.3 Artificial intelligence', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('334d210a-cb1b-59a6-a9a2-fd410d884ce0', 1, 'Name all four and their role: knowledge base (facts), rule base (IF–THEN rules), inference engine (applies rules to the facts to reach conclusions), user interface (asks questions and gives the diagnosis with an explanation).') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('470c878d-07c3-5920-af8b-197eddc57b71', 'fde0dc5c-cf56-5890-ab53-3152e2c4fc37', '7f09772a-bb5c-5ea8-abf7-da1bb142f3d8', null, 'Explain what is meant by machine learning.', '["A program improves by learning from data without being reprogrammed","A programmer writes new code each time the program makes a mistake","A computer runs the same fixed instructions a little faster each time","A robot copies exactly what a human shows it only once"]'::jsonb, 'Machine learning systems learn from training data and improve automatically.', false, 'paper', '6.3 Artificial intelligence', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('470c878d-07c3-5920-af8b-197eddc57b71', 0, 'Key phrase: the program can change its own data/behaviour based on experience (training data), so its performance improves without a programmer rewriting it. Example: spam filters, recommendations.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
